"""Test SVG documents for tools/svg_interop.py. Each is drawn by us and by Chromium and compared."""
import base64, struct, zlib

def tiny_png():
    w, h = 4, 4
    raw = b''.join(b'\x00' + b''.join(bytes([r * 60, g * 60, 128, 255]) for r in range(4) for g in [y]) for y in range(h))
    def chunk(t, d):
        c = struct.pack('>I', len(d)) + t + d
        return c + struct.pack('>I', zlib.crc32(t + d))
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b'')

IMG = base64.b64encode(tiny_png()).decode()
